/* @autogenerated */
package net.civeira.phylax.common.security.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Duration;
import java.time.ZonedDateTime;
import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.AuthenticationContext;
import net.civeira.phylax.common.security.AuthenticationLevel;

@DisplayName("AuthenticationContextImpl map conversion")
class AuthenticationContextImplUnitTest {

  @Test
  @DisplayName("Should round-trip every field through a map")
  void shouldRoundTripThroughMap() {
    // Arrange — a fully populated context
    ZonedDateTime at = ZonedDateTime.parse("2026-01-02T03:04:05Z");
    AuthenticationContext context =
        AuthenticationContextImpl.builder().level(AuthenticationLevel.MFA).mfa(true)
            .rememberMe(true).impersonated(true).secureTransport(true).authenticatedAt(at)
            .authenticationAge(Duration.ofSeconds(90)).authenticationMethod("pwd").sessionId("sid")
            .authenticatedActor(ActorImpl.builder().uid("real").build())
            .effectiveActor(ActorImpl.builder().uid("effective").build()).build();

    // Act — convert to a map and back
    AuthenticationContext restored =
        AuthenticationContextImpl.fromMap(AuthenticationContextImpl.toMap(context));

    // Assert — all values survive the conversion
    assertEquals(AuthenticationLevel.MFA, restored.getLevel());
    assertTrue(restored.isMfa());
    assertTrue(restored.isRememberMe());
    assertTrue(restored.isImpersonated());
    assertTrue(restored.isSecureTransport());
    assertEquals(at, restored.getAuthenticatedAt());
    assertEquals(Duration.ofSeconds(90), restored.getAuthenticationAge());
    assertEquals("pwd", restored.getAuthenticationMethod());
    assertEquals("sid", restored.getSessionId());
    assertEquals("real", restored.getAuthenticatedActor().getUid());
    assertEquals("effective", restored.getEffectiveActor().getUid());
  }

  @Test
  @DisplayName("Should parse textual values and default missing ones")
  void shouldParseTextualAndMissingValues() {
    // Arrange — a map with strings, nulls and missing entries
    Map<String, Object> map = new HashMap<>();
    map.put("level", "PASSWORD");
    map.put("mfa", "true");
    map.put("rememberMe", null);
    map.put("authenticatedAt", "2026-01-02T03:04:05Z");
    map.put("authenticationAge", "1500");
    map.put("authenticatedActor", Map.of());
    map.put("effectiveActor", Map.of());

    // Act — build the context
    AuthenticationContext restored = AuthenticationContextImpl.fromMap(map);

    // Assert — strings are parsed and missing values defaulted
    assertEquals(AuthenticationLevel.PASSWORD, restored.getLevel());
    assertTrue(restored.isMfa());
    assertFalse(restored.isRememberMe());
    assertEquals(Duration.ofMillis(1500), restored.getAuthenticationAge());
    assertEquals("", restored.getAuthenticationMethod());
    assertEquals("", restored.getSessionId());
  }

  @Test
  @DisplayName("Should default a missing authentication age to zero")
  void shouldDefaultMissingAgeToZero() {
    Map<String, Object> map = new HashMap<>();
    map.put("level", "ANONYMOUS");
    map.put("authenticatedAt", "2026-01-02T03:04:05Z");
    map.put("authenticatedActor", Map.of());
    map.put("effectiveActor", Map.of());

    assertEquals(Duration.ZERO, AuthenticationContextImpl.fromMap(map).getAuthenticationAge());
  }
}
